export interface LogEntry {
  readonly moment:    string;   // "HH:MM:SS"
  readonly trace:     string;   // action description
  readonly voix:      string;   // source module
}

export interface MemoryLog {
  readonly entries:   readonly LogEntry[];
  readonly maxSize:   number;    // default 10 — newest on top
}

export function addEntry(log: MemoryLog, entry: LogEntry): MemoryLog {
  const entries = [entry, ...log.entries].slice(0, log.maxSize);
  return Object.freeze({ ...log, entries: Object.freeze(entries) });
}

