#[derive(Debug, Clone)]
pub struct LogEntry {
    pub moment: String,   // "HH:MM:SS"
    pub trace:  String,
    pub voix:   String,   // source module
}

#[derive(Debug, Clone)]
pub struct MemoryLog {
    pub entries:  Vec<LogEntry>,
    pub max_size: usize,
}

impl MemoryLog {
    pub fn add(&mut self, entry: LogEntry) {
        self.entries.insert(0, entry);
        self.entries.truncate(self.max_size);
    }
}
